const putENSSyncProjection = `-- name: PutENSSyncProjection :one
WITH existing AS (
    SELECT prior.source_id, prior.revision, prior.kind, prior.key, prior.deployment, prior.block_hash, prior.payload FROM ens_sync_projections prior
    WHERE prior.source_id = $1 AND prior.kind = $2 AND prior.key = $3
    ORDER BY prior.revision DESC LIMIT 1
), changed AS (
    UPDATE ens_sync_progress p SET projection_revision = p.projection_revision + 1
    WHERE p.source_id = $1 AND p.projection_revision = $4
      AND NOT EXISTS (SELECT 1 FROM ens_sync_projections same
          WHERE same.source_id = p.source_id AND same.kind = $2 AND same.key = $3
            AND same.deployment = $5 AND same.block_hash = $6 AND same.payload = $7::jsonb
            AND NOT EXISTS (SELECT 1 FROM ens_sync_projections later WHERE later.source_id = same.source_id
                AND later.kind = same.kind AND later.key = same.key AND later.revision > same.revision))
    RETURNING p.source_id, p.projection_revision
), inserted AS (
    INSERT INTO ens_sync_projections(source_id, revision, kind, key, deployment, block_hash, payload)
    SELECT source_id, projection_revision, $2, $3, $5, $6, $7 FROM changed
    RETURNING revision
)
SELECT revision FROM inserted
UNION ALL
SELECT revision FROM existing WHERE existing.deployment = $5 AND existing.block_hash = $6 AND existing.payload = $7::jsonb
`

type PutENSSyncProjectionParams struct {
	SourceID         int64  `db:"source_id" json:"source_id"`
	Kind             string `db:"kind" json:"kind"`
	Key              string `db:"key" json:"key"`
	ExpectedRevision int64  `db:"expected_revision" json:"expected_revision"`
	Deployment       []byte `db:"deployment" json:"deployment"`
	BlockHash        []byte `db:"block_hash" json:"block_hash"`
	Payload          []byte `db:"payload" json:"payload"`
}

func (q *Queries) PutENSSyncProjection(ctx context.Context, arg PutENSSyncProjectionParams) (int64, error) {
	row := q.db.QueryRow(ctx, putENSSyncProjection,
		arg.SourceID,
		arg.Kind,
		arg.Key,
		arg.ExpectedRevision,
		arg.Deployment,
		arg.BlockHash,
		arg.Payload,
	)
	var revision int64
	err := row.Scan(&revision)
	return revision, err
}

const readENSSyncCandidate = `-- name: ReadENSSyncCandidate :one
SELECT c.id, c.requested_generation, c.minimum_generation, s.namespace, p.state AS source_state, p.revision,
    p.healthy_until, p.target_hash, p.scanned_hash,
    COALESCE(target.canonical AND (s.namespace <> 'custom_ens' OR EXISTS (
        SELECT 1 FROM canonical_blocks cb JOIN chains core ON core.chain_id = cb.chain_id AND core.genesis_hash = s.genesis_hash WHERE cb.chain_id = s.target_chain_id AND cb.number = target.number AND cb.block_hash = target.hash)), false)::boolean AS coverage_canonical,
    o.generation, o.source_revision, o.outcome, o.name, o.address, o.resolver, o.reverse_resolver,
    o.valid_until, o.block_hash, COALESCE(pub.id, 0)::bigint AS publication_id, pub.retain_until,
    COALESCE(b.canonical AND j.state = 'complete' AND j.target_hash = o.block_hash AND j.source_revision = o.source_revision AND NOT EXISTS (
          SELECT 1 FROM ens_sync_job_dependencies dep
          JOIN ens_sync_projections fact ON fact.source_id = dep.source_id AND fact.kind = dep.kind AND fact.key = dep.key AND fact.revision = dep.revision
          JOIN ens_sync_blocks fact_block ON fact_block.source_id = fact.source_id AND fact_block.hash = fact.block_hash
          JOIN ens_sync_blocks target_block ON target_block.source_id = j.source_id AND target_block.hash = j.target_hash
          WHERE dep.source_id = j.source_id AND dep.job_id = j.id
            AND (NOT fact_block.canonical OR fact_block.number > target_block.number OR EXISTS (
                SELECT 1 FROM ens_sync_projections newer
                  JOIN ens_sync_blocks newer_block ON newer_block.source_id = newer.source_id AND newer_block.hash = newer.block_hash AND newer_block.canonical
                  WHERE newer.source_id = dep.source_id
                  AND newer.kind = dep.kind AND newer.key = dep.key AND newer.revision > dep.revision))) AND (s.namespace <> 'custom_ens' OR EXISTS (
        SELECT 1 FROM canonical_blocks cb JOIN chains core ON core.chain_id = cb.chain_id AND core.genesis_hash = s.genesis_hash WHERE cb.chain_id = s.target_chain_id AND cb.number = b.number AND cb.block_hash = b.hash AND cb.updated_at = j.core_canonical_at)), false)::boolean AS canonical
FROM ens_sync_sources s
JOIN ens_sync_progress p ON p.source_id = s.id
LEFT JOIN ens_sync_blocks target ON target.source_id = s.id AND target.hash = p.target_hash
JOIN ens_sync_candidates c ON c.source_id = s.id
LEFT JOIN LATERAL (
    SELECT id, source_id, candidate_id, observation_id, published_at, retain_until FROM ens_sync_publications v WHERE v.source_id = c.source_id AND v.candidate_id = c.id
      AND ($1::bigint = 0 OR v.id = $1::bigint)
    ORDER BY v.id DESC LIMIT 1
) pub ON true
LEFT JOIN ens_sync_observations o ON o.id = pub.observation_id
LEFT JOIN ens_sync_blocks b ON b.source_id = o.source_id AND b.hash = o.block_hash
LEFT JOIN ens_sync_jobs j ON j.id = o.job_id AND j.generation = o.generation AND j.candidate_id = o.candidate_id AND j.source_id = o.source_id
WHERE s.id = $2 AND s.target_chain_id = $3 AND s.policy_digest = $4
  AND c.direction = $5 AND c.lookup_key = $6 AND c.coin_type = $7
`

type ReadENSSyncCandidateParams struct {
	PublicationID int64          `db:"publication_id" json:"publication_id"`
	SourceID      int64          `db:"source_id" json:"source_id"`
	TargetChainID pgtype.Numeric `db:"target_chain_id" json:"target_chain_id"`
	PolicyDigest  []byte         `db:"policy_digest" json:"policy_digest"`
	Direction     string         `db:"direction" json:"direction"`
	LookupKey     string         `db:"lookup_key" json:"lookup_key"`
	CoinType      pgtype.Numeric `db:"coin_type" json:"coin_type"`
}

type ReadENSSyncCandidateRow struct {
	ID                  int64              `db:"id" json:"id"`
	RequestedGeneration int64              `db:"requested_generation" json:"requested_generation"`
	MinimumGeneration   int64              `db:"minimum_generation" json:"minimum_generation"`
	Namespace           string             `db:"namespace" json:"namespace"`
	SourceState         string             `db:"source_state" json:"source_state"`
	Revision            int64              `db:"revision" json:"revision"`
	HealthyUntil        pgtype.Timestamptz `db:"healthy_until" json:"healthy_until"`
	TargetHash          []byte             `db:"target_hash" json:"target_hash"`
	ScannedHash         []byte             `db:"scanned_hash" json:"scanned_hash"`
	CoverageCanonical   bool               `db:"coverage_canonical" json:"coverage_canonical"`
	Generation          *int64             `db:"generation" json:"generation"`
	SourceRevision      *int64             `db:"source_revision" json:"source_revision"`
	Outcome             *string            `db:"outcome" json:"outcome"`
	Name                *string            `db:"name" json:"name"`
	Address             []byte             `db:"address" json:"address"`
	Resolver            []byte             `db:"resolver" json:"resolver"`
	ReverseResolver     []byte             `db:"reverse_resolver" json:"reverse_resolver"`
	ValidUntil          pgtype.Timestamptz `db:"valid_until" json:"valid_until"`
	BlockHash           []byte             `db:"block_hash" json:"block_hash"`
	PublicationID       int64              `db:"publication_id" json:"publication_id"`
	RetainUntil         pgtype.Timestamptz `db:"retain_until" json:"retain_until"`
	Canonical           bool               `db:"canonical" json:"canonical"`
}

func (q *Queries) ReadENSSyncCandidate(ctx context.Context, arg ReadENSSyncCandidateParams) (ReadENSSyncCandidateRow, error) {
	row := q.db.QueryRow(ctx, readENSSyncCandidate,
		arg.PublicationID,
		arg.SourceID,
		arg.TargetChainID,
		arg.PolicyDigest,
		arg.Direction,
		arg.LookupKey,
		arg.CoinType,
	)
	var i ReadENSSyncCandidateRow
	err := row.Scan(
		&i.ID,
		&i.RequestedGeneration,
		&i.MinimumGeneration,
		&i.Namespace,
		&i.SourceState,
		&i.Revision,
		&i.HealthyUntil,
		&i.TargetHash,
		&i.ScannedHash,
		&i.CoverageCanonical,
		&i.Generation,
		&i.SourceRevision,
		&i.Outcome,
		&i.Name,
		&i.Address,
		&i.Resolver,
		&i.ReverseResolver,
		&i.ValidUntil,
		&i.BlockHash,
		&i.PublicationID,
		&i.RetainUntil,
		&i.Canonical,
	)
	return i, err
}

const retryENSSyncJob = `-- name: RetryENSSyncJob :execrows
UPDATE ens_sync_jobs SET state = CASE WHEN attempts >= max_attempts OR $1 >= deadline THEN 'failed' ELSE 'queued' END,
    failure_code = $2, retry_at = $1, lease_token = NULL, lease_until = NULL
WHERE source_id = $3 AND id = $4 AND state = 'leased'
  AND lease_token = $5 AND lease_until > clock_timestamp()
`

type RetryENSSyncJobParams struct {
	RetryAt     pgtype.Timestamptz `db:"retry_at" json:"retry_at"`
	FailureCode *string            `db:"failure_code" json:"failure_code"`
	SourceID    int64              `db:"source_id" json:"source_id"`
	JobID       int64              `db:"job_id" json:"job_id"`
	LeaseToken  pgtype.UUID        `db:"lease_token" json:"lease_token"`
}

func (q *Queries) RetryENSSyncJob(ctx context.Context, arg RetryENSSyncJobParams) (int64, error) {
	result, err := q.db.Exec(ctx, retryENSSyncJob,
		arg.RetryAt,
		arg.FailureCode,
		arg.SourceID,
		arg.JobID,
		arg.LeaseToken,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setENSSyncTarget = `-- name: SetENSSyncTarget :execrows
UPDATE ens_sync_progress p SET target_number = b.number, target_hash = b.hash,
    healthy_until = $1, state = 'active', failure_code = NULL
FROM ens_sync_blocks b
WHERE p.source_id = $2 AND b.source_id = p.source_id AND b.hash = $3
  AND b.canonical AND p.state IN ('pending', 'active')
  AND (p.target_number IS NULL OR b.number >= p.target_number)
  AND (p.target_number IS DISTINCT FROM b.number OR p.target_hash = b.hash)
`

func (q *Queries) SetENSSyncTarget(ctx context.Context, healthyUntil pgtype.Timestamptz, sourceID int64, blockHash []byte) (int64, error) {
	result, err := q.db.Exec(ctx, setENSSyncTarget, healthyUntil, sourceID, blockHash)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
